  Theorem ax_sound_clean : forall vals R M msF mo (code : word),
    length vals = 40%nat -> vals_ev vals 0 = sp0 -> vals_ev vals 2 = code ->
    regs_ok (ENV vals) x_sr R -> know_ok RSEGS (ENV vals) M (ax_kn true false) ->
    lzok RSEGS L S Zr (mkCfg msF mo) -> restrict L S msF = mkst R (Z_to_bv 64 AEXIT) M (seg_rom RSEGS) ->
    realizes RSEGS (mkCfg msF mo) (t_exit (bv_and code (Z_to_bv 64 255)) (m_fs mo)).
