  Record axH (two : bool) (mem : word -> option byte) (sp : word) (tid can : Z) (we re ro : word) : Prop := AXH {
    Xsp16 : (bv_unsigned sp mod 16 = 0)%Z;
    XspLo : (ASP_LO <= bv_unsigned sp)%Z;
    XspHi : (bv_unsigned sp <= ASP_HI)%Z;
    Xstk  : stk_ok RSEGS mem sp 400;
    Xtid  : (0 < tid < 2147483648)%Z;
    Xtidc : rdn RSEGS mem (Z_to_bv 64 0x65d408) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 tid));
    Ximg  : forall i, (0x10000 <= i < 0x4d000)%Z -> mem (Z_to_bv 64 i) = None;
    Xgot  : forall i, (0x115000 <= i < 0x11d000)%Z -> mem (Z_to_bv 64 i) = None;
    Xuse2 : forall i, (0x11fd18 <= i < 0x11fd20)%Z -> mem (Z_to_bv 64 i) = None;
    Xglb  : forall i, (0x11fe08 <= i < 0x125dc0)%Z -> mem (Z_to_bv 64 i) = None;
    Xcan  : rdn RSEGS mem (Z_to_bv 64 0x67d4f0) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 can));
    Xcan64 : (0 <= can < 2 ^ 64)%Z;
    Xew1  : rdn RSEGS mem (Z_to_bv 64 0x11fc58) 8 = Some (word_to_le_bytes 8 we);
    Xew2  : rdn RSEGS mem (Z_to_bv 64 0x11fc68) 8 = Some (word_to_le_bytes 8 we);
    Xer1  : rdn RSEGS mem (Z_to_bv 64 0x11fc38) 8 = Some (word_to_le_bytes 8 re);
    Xer2  : rdn RSEGS mem (Z_to_bv 64 0x11fc40) 8 = Some (word_to_le_bytes 8 re);
    Xor1  : rdn RSEGS mem (Z_to_bv 64 0x11fd28) 8 = Some (word_to_le_bytes 8 ro);
    Xor2  : rdn RSEGS mem (Z_to_bv 64 0x11fd30) 8 = Some (word_to_le_bytes 8 ro);
    Xcells : cells_ok mem (ax_lit_cells two);
    Xshw  : forall (a : word) (n : nat), (0x7fffa000 <= bv_unsigned a)%Z -> (bv_unsigned a + Z.of_nat n <= 0x7fffa000 + 0xcde00)%Z ->
              store_ok RSEGS mem a n = true }.

  Definition x_vals (regs : bvmap 5 word) (sp : word) (tid : Z) (code : word) (can wp : Z) (we re ro : word) : list word :=
    [sp; Z_to_bv 64 tid; code; Z_to_bv 64 can; Z_to_bv 64 wp; we; re; ro] ++ junk_vals regs.

  Lemma x_ev_junk : forall regs sp tid code can wp we re ro i, (8 <= i < 40)%nat ->
